'use strict';
/**
 * F105-PATCH-MODULE v2 — generated by apply-f105.js
 * F#105-EGRESS: gzip + response cache + CDN cache-control. Zero dependencies.
 * Delete this file and the require line in server.js to fully uninstall.
 * Kill switch: env F105_DISABLE=1. Stats: GET /_f105stats
 */
const zlib = require('zlib');
const crypto = require('crypto');

function intEnv(name, dflt) {
  const v = parseInt(process.env[name], 10);
  return Number.isFinite(v) ? v : dflt;
}

function lru(max) {
  const m = new Map();
  return {
    get(k) { const v = m.get(k); if (v === undefined) return undefined; m.delete(k); m.set(k, v); return v; },
    set(k, v) { if (m.has(k)) m.delete(k); m.set(k, v); while (m.size > max) m.delete(m.keys().next().value); },
    del(k) { m.delete(k); },
    size() { return m.size; },
  };
}

module.exports = function install(app) {
  const DISABLED = process.env.F105_DISABLE === '1';
  const PDP_TTL = intEnv('F105_PDP_TTL', 60000);
  const REL_TTL = intEnv('F105_RELATED_TTL', 300000);
  const MAX_ENTRIES = intEnv('F105_CACHE_MAX', 20000);
  const MAX_BYTES = intEnv('F105_MAX_BYTES', 1500000);
  const PDP_RE = new RegExp(process.env.F105_PDP_RE || '^/api/products/[^/]+/?$');
  const REL_RE = new RegExp(process.env.F105_REL_RE || '^/api/products/[^/]+/related/?$|^/api/related/[^/]+/?$');
  const CC_RE = new RegExp(process.env.F105_CC_RE || '^/api/(products|related)');

  const stats = { gzip: 0, pdp: { hit: 0, miss: 0 }, rel: { hit: 0, miss: 0 }, bypass: 0 };
  const started = Date.now();

  if (intEnv('F105_STATS', 1)) {
    setInterval(function () {
      const p = stats.pdp, r = stats.rel;
      const ph = (p.hit + p.miss) ? Math.round(100 * p.hit / (p.hit + p.miss)) : 0;
      const rh = (r.hit + r.miss) ? Math.round(100 * r.hit / (r.hit + r.miss)) : 0;
      console.log('[F105] up=' + Math.round((Date.now() - started) / 60000) + 'min gzip=' + stats.gzip +
        ' pdp hit=' + ph + '% (' + p.hit + '/' + (p.hit + p.miss) + ')' +
        ' related hit=' + rh + '% (' + r.hit + '/' + (r.hit + r.miss) + ') bypass=' + stats.bypass);
    }, 300000).unref();
  }

  app.get('/_f105stats', function (req, res) {
    res.json({ ok: true, module: 'F105-PATCH-MODULE v2', disabled: DISABLED, uptimeSec: Math.round((Date.now() - started) / 1000), stats: stats, cacheSizes: { pdp: pdpCache.size(), related: relCache.size() } });
  });

  // ── L1: gzip (buffers up to F105_MAX_BYTES, compresses JSON/text at end) ──
  app.use(function f105Gzip(req, res, next) {
    if (DISABLED) return next();
    const ae = String(req.headers['accept-encoding'] || '');
    if (!/\bgzip\b/.test(ae)) return next();
    const chunks = [];
    let size = 0, active = false, decided = false, passthrough = false;
    const oWrite = res.write.bind(res);
    const oEnd = res.end.bind(res);
    res.write = function (c, enc, cb) {
      if (!decided) decide();
      if (passthrough) return oWrite(c, enc, cb);
      if (Buffer.isBuffer(c)) { push(c); return true; }
      push(Buffer.from(String(c), enc || 'utf8'));
      return true;
    };
    res.end = function (c, enc, cb) {
      if (!decided) decide();
      if (passthrough) return oEnd(c, enc, cb);
      if (typeof c === 'string') push(Buffer.from(c, enc || 'utf8'));
      else if (Buffer.isBuffer(c)) push(c);
      else if (c) { passthrough = true; return oEnd(c, enc, cb); }
      const buf = Buffer.concat(chunks);
      const gz = zlib.gzipSync(buf, { level: zlib.constants.Z_BEST_SPEED });
      res.setHeader('Content-Encoding', 'gzip');
      res.setHeader('Content-Length', String(gz.length));
      const v = String(res.getHeader('Vary') || '');
      if (v.indexOf('Accept-Encoding') === -1) res.setHeader('Vary', (v ? v + ', ' : '') + 'Accept-Encoding');
      stats.gzip++;
      return oEnd(gz);
    };
    function push(b) { size += b.length; if (size > MAX_BYTES) { passthrough = true; return; } chunks.push(b); }
    function decide() {
      decided = true;
      const ct = String(res.getHeader('Content-Type') || '');
      const already = String(res.getHeader('Content-Encoding') || '');
      const ok200 = !res.statusCode || res.statusCode === 200;
      if (already || !ok200 || !/json|javascript|text|xml/i.test(ct)) passthrough = true;
    }
    next();
  });

  // ── L2/L3/L4: response cache + CDN cache-control + identity guards ──
  const pdpCache = lru(MAX_ENTRIES);
  const relCache = lru(MAX_ENTRIES);
  app.use(function f105Cache(req, res, next) {
    if (DISABLED || req.method !== 'GET') return next();
    const p = (req.path !== undefined) ? req.path : String(req.url || '').split('?')[0];
    // L4 — any identity (admin panel, user account) → never cache
    if (req.headers.cookie || req.headers.authorization) {
      if (CC_RE.test(p)) { stats.bypass++; res.setHeader('x-f105-cache', 'BYPASS'); }
      return next();
    }
    // L3 — CDN cache-control for the product family (routes may override later)
    if (CC_RE.test(p) && !res.getHeader('Cache-Control')) {
      res.setHeader('Cache-Control', 'public, max-age=30, s-maxage=300, stale-while-revalidate=86400');
    }
    const isRel = REL_RE.test(p);
    const isPdp = !isRel && PDP_RE.test(p);
    if (!isRel && !isPdp) return next();
    const cache = isRel ? relCache : pdpCache;
    const ttl = isRel ? REL_TTL : PDP_TTL;
    const key = req.originalUrl || req.url;
    const hit = cache.get(key);
    if (hit && hit.exp > Date.now()) {
      if (isRel) stats.rel.hit++; else stats.pdp.hit++;
      Object.keys(hit.h).forEach(function (k) {
        const lk = k.toLowerCase();
        if (lk !== 'content-length' && lk !== 'content-encoding' && lk !== 'etag') res.setHeader(k, hit.h[k]);
      });
      if (hit.etag) res.setHeader('ETag', hit.etag);
      const inm = req.headers['if-none-match'];
      if (inm && hit.etag && inm === hit.etag) {
        res.setHeader('x-f105-cache', 'HIT');
        res.status(304);
        return res.end();
      }
      res.setHeader('x-f105-cache', 'HIT');
      res.status(hit.s);
      return res.end(hit.b);
    }
    if (hit) cache.del(key);
    if (isRel) stats.rel.miss++; else stats.pdp.miss++;
    res.setHeader('x-f105-cache', 'MISS');
    const chunks = [];
    let size = 0, capturing = true;
    const oWrite = res.write.bind(res);
    const oEnd = res.end.bind(res);
    res.write = function (c, enc, cb) {
      if (capturing) {
        if (!Buffer.isBuffer(c)) { capturing = false; return oWrite(c, enc, cb); }
        size += c.length;
        if (size > MAX_BYTES) { capturing = false; chunks.length = 0; return oWrite(c, enc, cb); }
        chunks.push(c);
        return true;
      }
      return oWrite(c, enc, cb);
    };
    res.end = function (c, enc, cb) {
      if (capturing) {
        capturing = false;
        if (typeof c === 'string') { chunks.push(Buffer.from(c, enc || 'utf8')); c = undefined; }
        else if (Buffer.isBuffer(c)) { chunks.push(c); c = undefined; }
        if (chunks.length === 0) return oEnd(c, enc, cb);
        const buf = Buffer.concat(chunks);
        if (res.statusCode === 200 && buf.length > 0 && buf.length <= MAX_BYTES) {
          const etag = '"' + crypto.createHash('md5').update(buf).digest('hex') + '"';
          res.setHeader('ETag', etag);
          const h = res.getHeaders();
          delete h['content-length']; delete h['content-encoding']; delete h['etag'];
          cache.set(key, { s: 200, h: h, b: buf, etag: etag, exp: Date.now() + ttl });
        }
        res.setHeader('Content-Length', String(buf.length));
        return oEnd(buf);
      }
      return oEnd(c, enc, cb);
    };
    next();
  });

  console.log('[F105] egress patch active' + (DISABLED ? ' (DISABLED via F105_DISABLE=1)' : '') +
    ' — pdp ' + (PDP_TTL / 1000) + 's / related ' + (REL_TTL / 1000) + 's / lru ' + MAX_ENTRIES);
};
